window.REPORT_PRELOAD_CACHE["USFD.html"] = {"version":"cb037390a2c7492aa32e55c42ccb153bc6358748cd3398f493d674b0d5b81717","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>美国食品控股 US Foods Holding Corp (NYSE: USFD) 深度商业与投资价值分析报告</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n foodred: {\n 300: '#FCA5A5',\n 400: '#F87171',\n 500: '#E11D48',\n 600: '#BE123C',\n 700: '#9F1239',\n },\n foodblue: {\n 400: '#38BDF8',\n 500: '#0EA5E9',\n 600: '#0284C7',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar { width: 6px; height: 6px; }\n ::-webkit-scrollbar-track { background: transparent; }\n ::-webkit-scrollbar-thumb { background: #94A3B8; border-radius: 3px; }\n .dark ::-webkit-scrollbar-thumb { background: #475569; }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print { display: none !important; }\n main { margin-left: 0 !important; padding: 0 !important; }\n section { break-inside: avoid; }\n }\n\n .report-card { transition: transform 0.2s ease, box-shadow 0.2s ease; }\n .report-card:hover { transform: translateY(-2px); }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(225, 29, 72, 0.22) 0%, rgba(16, 185, 129, 0.05) 100%);\n border-left: 3px solid #E11D48;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-foodred-500 selection:text-white transition-colors duration-200\">\n\n <!-- 全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-foodred-600 via-foodred-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-foodred-600 to-navy-900 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n USFD\n </div>\n <div>\n <div class=\"text-[11px] text-foodred-300 font-semibold tracking-wider uppercase\">NYSE: USFD · Foodservice</div>\n <div class=\"text-sm font-bold leading-tight\">美国食品控股深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 text-slate-300\" aria-label=\"主题切换\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 text-white\" aria-label=\"菜单\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端抽屉 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">USFD 研报目录</span>\n <button onclick=\"toggleMobileMenu()\" class=\"text-slate-400 hover:text-white\">✕</button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">00. 执行摘要与最新财报</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">01. 商业模式与产品生态</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">02. 核心竞争优势与供应链壁垒</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">03. 财务表现与 Q3 2026 业绩洞察</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">04. 同业竞争与市场格局</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">05. 估值展望与投资策略</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">06. 跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>美股食品供应链龙头研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 财报)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧边栏 (280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-foodred-600 to-navy-900 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-foodred-600/25\">\n USFD\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-foodred-300 bg-foodred-500/15 px-2 py-0.5 rounded\">NYSE: USFD</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">美国食品控股研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 美国第二大食品餐饮供应链巨头 · 覆盖全国独立餐厅、医疗机构与酒店的现代化智慧物流网络\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">最新股价 (Q4 2026)</span>\n <span class=\"font-mono font-bold text-white\">~$103.61 <span class=\"text-slate-400 text-[10px]\">($88-$120)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">第三季度净销售额</span>\n <span class=\"font-mono font-bold text-emerald-400\">$104亿 (+2.1% YoY)</span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">调整后 EBITDA</span>\n <span class=\"font-mono font-bold text-foodred-300\">$5.55亿 (+9.9% YoY)</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">报告核心章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-foodred-400 mr-2\">00</span>执行摘要与最新财报</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>商业模式与产品生态</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>核心竞争优势与供应链壁垒</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>财务表现与 Q3 2026 业绩洞察</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>同业竞争与市场格局</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>估值展望与投资策略</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">页面显示模式</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-foodred-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-foodred-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色模式</span>\n <span class=\"hidden dark:inline\">浅色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-foodred-600 to-foodred-700 hover:from-foodred-700 text-white text-xs font-extrabold transition cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span class=\"text-white\">打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. 封面与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-foodred-500/15 text-foodred-700 dark:text-foodred-300 font-bold border border-foodred-500/30\">机构评级：买入 (Outperform / Buy)</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">覆盖基准：2026年第三季度财报与行业展望</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>股票代码：NYSE: USFD</span>\n <span>总市值：~$163 亿</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#E11D48 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-foodred-500/20 border border-foodred-400/40 text-foodred-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-foodred-400 animate-pulse\"></span>\n <span>EXECUTIVE SUMMARY · 独立餐厅大增 5% × 调整后 EBITDA 劲增 9.9% × AI 数字化供应链降本增效</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 美国食品控股 US Foods Holding Corp. (NYSE: USFD) 深度商业与投资价值分析报告\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 美国食品控股（US Foods Holding Corp., 代码：<strong class=\"text-white\">USFD</strong>）作为全美规模第二大的餐饮供应链与食品分销巨头，在刚刚发布的 <strong class=\"text-foodred-300\">2026财年第三季度财报</strong>中展现出极强的抗周期韧性 [cite: 1.1.1]。本季度净销售额达到 <strong class=\"text-white\">$104亿美元</strong>（同比增长 2.1%），净利润大增 42.5% 至 <strong class=\"text-emerald-400\">$2.18亿美元</strong>，调整后 EBITDA 飙升 9.9% 至 <strong class=\"text-foodred-300\">$5.55亿美元</strong> [cite: 1.1.1]。\n 公司凭借连续 22 个季度实现独立餐厅业务增长、Pronto 电子商务快速放量以及 AI 驱动的供应链优化，正稳步巩固其在万亿级餐饮分销市场的护城河。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">Q3 营收与盈利双升</div>\n <div class=\"text-white font-semibold\">净销售额 $104 亿 (+2.1%)，净利润大增 42.5% 至 $2.18 亿，盈利能力显著扩张 [cite: 1.1.1]</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">独立餐厅强劲增长</div>\n <div class=\"text-foodred-300 font-semibold\">独立餐厅出货量 (Case Volume) 连续 22 个季度实现正增长，本季度大增 5.0% [cite: 1.1.1, 1.1.3]</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">AI 与数字供应链赋能</div>\n <div class=\"text-emerald-400 font-semibold\">AI 计划带来超过 $7500 万美元的 EBITDA 贡献，预计明年将突破 $1.1 亿美元 [cite: 1.1.3]</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 四大核心 KPI 指标卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 2026 净销售额</span>\n <span class=\"p-1.5 rounded-lg bg-foodred-500/15 text-foodred-600 dark:text-foodred-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$104亿</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">+2.1% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 第三季度实现净销售额 104.02 亿美元，整体业务规模在复杂宏观环境下稳步扩张 [cite: 1.1.1, 1.2.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>调整后 EBITDA</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$5.55亿</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">+9.9% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 利润率提升 38 个基点至 5.3%，彰显出卓越的供应链成本控制与毛利优化能力 [cite: 1.1.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>调整后每股收益 (EPS)</span>\n <span class=\"p-1.5 rounded-lg bg-foodblue-500/15 text-foodblue-600 dark:text-foodblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$1.26</span>\n <span class=\"text-xs font-bold text-foodblue-600 dark:text-foodblue-400 bg-foodblue-500/15 px-2 py-0.5 rounded\">+17.8% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 调整后摊薄 EPS 达到 $1.26（GAAP 摊薄 EPS 为 $1.00，大增 49.3%），超出市场核心预期 [cite: 1.1.1, 1.1.3]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>独立餐厅出货量增长</span>\n <span class=\"p-1.5 rounded-lg bg-foodred-500/15 text-foodred-600 dark:text-foodred-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">+5.0%</span>\n <span class=\"text-xs font-bold text-foodred-700 dark:text-foodred-300 bg-foodred-500/15 px-2 py-0.5 rounded\">连续 22 季增长</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 独立餐厅 Case Volume 连续 22 个季度实现领先行业的正增长（本季达 5.0%），构筑强劲业务基本盘 [cite: 1.1.2, 1.1.3]。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 商业模式与产品生态\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-foodred-600 dark:text-foodred-400\">Section 01 · Business Model & Product Ecosystem</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 商业模式与产品生态：全美餐饮供应链的核心枢纽</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">B2B 食品分销 · 覆盖独立餐厅、连锁餐饮与医疗机构</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">US Foods 核心业务板块与产品构成</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\">生鲜食材、冷冻食品、干货与餐饮运营数字化解决方案全景</p>\n </div>\n <span class=\"px-2.5 py-1 rounded bg-foodred-500/15 text-foodred-600 dark:text-foodred-400 text-xs font-bold\">全品类大宗分销商</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizSegmentChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业模式三大核心支柱</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-foodred-500/15 text-foodred-600 dark:text-foodred-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Broadline 广品类餐饮分销网络</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 向全美数十万家独立餐厅、酒店、学校及医疗机构提供超过 30 万种食品及厨房用品，实现一站式冷链配送。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-foodblue-500/15 text-foodblue-600 dark:text-foodblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Pronto 电子商务与数字工具矩阵</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 专为餐饮业主打造的数字订货平台 Pronto 今年业绩亮眼，预计全年销售额将突破 $13 亿美元，2027 年将冲刺 $17 亿规模 [cite: 1.1.3]。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">战略并购与本土特种分销整合</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 如近期收购位于佛罗里达州的 Prime Line Distributors，快速拓展地中海/意式特色食材供应品类，不断增厚高毛利产品线 [cite: 1.1.1, 1.1.3]。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">客户结构</span>\n <span class=\"font-bold text-foodred-600 dark:text-foodred-400\">独立餐厅占比高，抗风险与毛利极佳</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 核心竞争优势与供应链壁垒\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Competitive Advantages & Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 核心竞争优势与供应链壁垒：AI 赋能、规模效应与极高客户粘性</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽护城河 (Wide Moat)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-foodred-500/15 text-foodred-600 dark:text-foodred-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">AI 销售洞察与供应链自动化降本</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 运用 AI 销售洞察工具的客户采购额增速比行业快近 10%，同时物流端订单错误率（Order Markouts）减少 25%，货车短缺减少 10% [cite: 1.1.3]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">连续 22 季独立餐厅市占率扩张</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 独立餐厅客户对供应链服务的专业度与稳定性要求极高，USFD 凭借卓越的履约能力已连续 22 个季度实现独立餐厅出货量正增长 [cite: 1.1.2, 1.1.3]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-foodblue-500/15 text-foodblue-600 dark:text-foodblue-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全国性冷链物流与仓储网络</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 拥有覆盖全美的高效率配送中心与冷藏车队，能够保障生鲜食品在最短时间内送达餐饮终端，保障食品安全与新鲜度。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">稳健的资产负债表与现金流</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 前三季度经营活动现金流高达近 12 亿美元，净杠杆率维持在 2.4 倍的健康区间，具备充沛资本支撑内生增长与并购 [cite: 1.1.3]。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">供应链分销行业核心五维护城河雷达</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">US Foods vs 同业竞争对手综合评分（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三: 财务表现与 Q3 2026 业绩洞察\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-foodred-600 dark:text-foodred-400\">Section 03 · Financial Performance & Q3 2026 Earnings</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 财务表现与 Q3 2026 业绩洞察：毛利扩张与盈利超预期</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">毛利增长 8.6% · 调整后 EBITDA 增长 9.9% [cite: 1.1.1]</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-foodred-600 dark:text-foodred-400 uppercase\">Gross Profit (Q3 2026)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$19.04亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 毛利润同比增长 8.6%（达 19.04 亿美元），毛利率达 18.3%，受益于战略供应商管理与高毛利独立餐厅业务占比提升 [cite: 1.1.3, 1.2.4]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Operating Cash Flow</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$11.6亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 前 39 周运营现金流达到 11.6 亿美元（去年同期 10.76 亿），现金生成能力强劲，支撑股票回购与兼并收购 [cite: 1.1.2]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-foodblue-600 dark:text-foodblue-400 uppercase\">Share Repurchase</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$1.91亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n Q3 单季度回购股票金额达 1.91 亿美元（年初至今已回购 6.9 亿美元），展现管理层对公司长期价值的坚定信心 [cite: 1.1.1, 1.1.3]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Net Leverage Ratio</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">2.4 倍</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 净负债率保持在 2.4 倍的健康目标区间内，财务杠杆安全可控，具备充裕的融资灵活性 [cite: 1.1.3]。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">US Foods 近年营收与盈利走势趋势 ($ 亿美元)</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">主营业务营收稳步攀升，毛利率与 EBITDA 持续优化改善</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-foodred-700 dark:text-foodred-300 bg-foodred-500/15 px-2.5 py-1 rounded\">稳健增长通道</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"finTrendChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 同业竞争与市场格局\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-foodred-600 dark:text-foodred-400\">Section 04 · Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 同业竞争与市场格局：Sysco 行业领跑，USFD 聚焦独立餐厅高利润成长</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">美国餐饮分销双寡头格局：Sysco vs US Foods</span>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">公司名称与代码</th>\n <th class=\"py-4 px-4 min-w-[130px]\">市场地位</th>\n <th class=\"py-4 px-4 min-w-[140px]\">年化营收规模</th>\n <th class=\"py-4 px-4 min-w-[120px]\">独立餐厅策略</th>\n <th class=\"py-4 px-5 min-w-[240px]\">核心竞争优势与业务亮点</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\">\n <tr class=\"bg-foodred-500/5 dark:bg-foodred-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-foodred-700 text-white text-[10px] font-extrabold\">本文主角</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">US Foods Holding (NYSE: USFD)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">第二大分销商</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全美第二大</td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~$400 亿+</td>\n <td class=\"py-4 px-4 text-emerald-600 dark:text-emerald-400 font-semibold\">连续 22 季正增长</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>AI 数字化领先：</strong>Pronto 电商迅速放量，AI 销售工具赋能独立餐厅市占率连续 22 季度扩张，利润率持续领跑 [cite: 1.1.2, 1.1.3]。\n </td>\n </tr>\n\n <tr class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Sysco Corporation (NYSE: SYY)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">行业绝对龙头</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全美第一大</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~$750 亿+</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全球化广泛覆盖</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>规模效应绝对优势：</strong>全球化布局成熟，供应链网络极其庞大，为大型连锁餐饮首选供应商。\n </td>\n </tr>\n\n <tr class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Performance Food Group (NYSE: PFGC)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">第三大分销商</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全美第三大</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~$600 亿+</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">多渠道混合扩张</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>多品类并行：</strong>通过收购 Vistar 等特种渠道在便利店及糖果零食领域具备强大优势。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 估值展望与投资策略\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-foodred-600 dark:text-foodred-400\">Section 05 · Valuation Outlook & Investment Strategy</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 估值展望与投资策略：全年指引稳健，华尔街一致看好</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">目标价区间：$116 – $124（华尔街投行共识） [cite: 1.1.4]</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">乐观情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">目标价：$124+</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">Pronto 放量超预期</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>Pronto 数字化平台销售额加速突破 $17 亿美元，AI 供应链降本幅度超预期，独立餐厅业务持续强劲增长。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n Citi 给出目标价 $124 买入评级 [cite: 1.1.4]\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-foodred-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-foodred-500/15 text-foodred-700 dark:text-foodred-300 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-foodred-600 dark:text-foodred-400\">目标价：$116 – $120</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">全年指引顺利达成</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>公司达成 2026 全年调整后 EBITDA 增长 9%-11%、调整后 EPS 增长 18%-20% 的稳健指引 [cite: 1.1.1]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-foodred-600 dark:text-foodred-400\">\n BMO Capital 给出目标价 $120 买入评级 [cite: 1.1.4]\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">谨慎情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">目标价：$90 – $95</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">消费需求疲软与劳动力成本</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>宏观消费者信心指数承压导致餐饮堂食需求放缓，燃油成本上升及seller薪酬调整带来短期费用压力 [cite: 1.1.3]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 需密切跟踪通胀传导与劳动力市场波动\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-foodred-300 mb-3 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构投资策略建议</span>\n </h3>\n <p class=\"text-xs sm:text-sm text-slate-300 leading-relaxed\">\n US Foods Holding (USFD) 作为美股必需消费与供应链领域的优质标的，兼具防御属性与 AI 数字化成长动能。当前估值对应其近 18% 的调整后 EPS 增速具备较高性价比 [cite: 1.1.1]。建议投资者在宏观震荡期逢低布局，作为长线餐饮供应链赛道的配置核心。\n </p>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 跟踪 KPI 核查清单\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Regular Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 定期跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-foodred-500/15 text-foodred-700 dark:text-foodred-300 text-xs font-bold\">已核查 3 / 5 项 (60%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选 USFD 投资组合监控中的关键运营指标（本地状态自动保存）：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 独立餐厅出货量（Case Volume）保持正增长</span>\n <span class=\"text-[11px] font-mono text-foodred-600 dark:text-foodred-400 font-semibold shrink-0\">核心基本盘</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 维持连续多个季度独立餐厅出货量领先行业的正增长纪录（如本季 +5.0%） [cite: 1.1.1, 1.1.3]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 调整后 EBITDA 利润率持续稳健扩张</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">盈利能力指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控每季度调整后 EBITDA 利润率是否有同比提升（如 Q3 提升 38 个基点至 5.3%） [cite: 1.1.1]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. Pronto 数字化平台销售额稳步突破目标</span>\n <span class=\"text-[11px] font-mono text-foodblue-600 dark:text-foodblue-400 font-semibold shrink-0\">数字化渗透率</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪 Pronto 电商平台销售额向 13 亿美元（2026）及 17 亿美元（2027）迈进的进度 [cite: 1.1.3]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 净负债率（Net Leverage）保持在 2.0x-2.5x 区间</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">财务杠杆安全</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确保杠杆率维持在健康管理目标内，为股票回购与战略并购留出充足空间。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. AI 销售洞察及供应链效率提升达到全年预期</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">科技降本成效</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 验证 AI 项目对 EBITDA 的贡献额是否顺利突破 7500 万美元及向 1.1 亿美元迈进 [cite: 1.1.3]。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>美国食品控股 US Foods Holding Corp. (NYSE: USFD) 深度商业与投资价值分析报告 [cite: 1.1.1]</span>\n <span>数据基准：2026 年 Q3 财报与公开资本市场披露 [cite: 1.1.1]</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本报告基于 US Foods 公开披露的财务财报、SEC 申报文件及市场分析数据撰写，旨在提供结构化商业研究参考。报告中的前瞻性预测、目标价及财务推演不构成任何直接证券投资建议。\n </p>\n </footer>\n\n </div>\n </main>\n\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-foodred-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-foodred-400');\n }\n }\n });\n });\n\n const KPI_STORAGE_KEY = 'usfd_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizSegmentChartInstance = null;\n let moatRadarChartInstance = null;\n let finTrendChartInstance = null;\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizSegmentChart() {\n const ctx = document.getElementById('bizSegmentChart').getContext('2d');\n const colors = getChartColors();\n\n if (bizSegmentChartInstance) bizSegmentChartInstance.destroy();\n bizSegmentChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['生鲜食材 (Fresh Meat & Produce)', '冷冻食品 (Frozen Foods)', '干货杂货 (Dry Groceries)', '乳制品与禽蛋 (Dairy & Poultry)', '厨房用品与设备 (Equipment & Supplies)'],\n datasets: [\n {\n label: '产品矩阵分销比重估算 (%)',\n data: [28, 24, 22, 16, 10],\n backgroundColor: '#E11D48',\n borderRadius: 6,\n barThickness: 22\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `品类占比约: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 35,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initMoatRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (moatRadarChartInstance) moatRadarChartInstance.destroy();\n moatRadarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n 'AI 数字化与销售洞察领先度',\n '全国冷链物流与仓储网络',\n '独立餐厅客户服务粘性',\n '供应链采购成本与规模优势',\n '资产负债表与现金生成力'\n ],\n datasets: [\n {\n label: 'US Foods (USFD)',\n data: [9.6, 9.5, 9.8, 9.4, 9.5],\n borderColor: '#E11D48',\n backgroundColor: 'rgba(225, 29, 72, 0.22)',\n pointBackgroundColor: '#E11D48',\n borderWidth: 2.5\n },\n {\n label: '行业平均水平',\n data: [7.5, 8.5, 8.0, 8.5, 8.0],\n borderColor: '#0EA5E9',\n backgroundColor: 'rgba(14, 165, 233, 0.12)',\n pointBackgroundColor: '#0EA5E9',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initFinTrendChart() {\n const ctx = document.getElementById('finTrendChart').getContext('2d');\n const colors = getChartColors();\n\n if (finTrendChartInstance) finTrendChartInstance.destroy();\n finTrendChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', '2026 (F)'],\n datasets: [\n {\n type: 'bar',\n label: '全年营业收入 Net Sales ($ 亿)',\n data: [356, 378, 394, 412],\n backgroundColor: 'rgba(225, 29, 72, 0.85)',\n borderRadius: 6,\n barThickness: 32,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '调整后 EBITDA ($ 亿)',\n data: [14.2, 15.8, 17.5, 19.2],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 0,\n max: 450,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + '亿' },\n title: { display: true, text: '营业收入 ($亿)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 25,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v + '亿' },\n title: { display: true, text: 'EBITDA ($亿)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizSegmentChart();\n initMoatRadarChart();\n initFinTrendChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n initBizSegmentChart();\n initMoatRadarChart();\n initFinTrendChart();\n });\n </script>\n</body>\n</html>\n"};
